<script setup lang="ts">
import { onMounted, ref } from "vue"; import { api } from "../lib/request";
const items=ref<any[]>([]), name=ref(""), scopes=ref(["retrieve","chat"]), secret=ref(""), error=ref(""); async function load(){try{items.value=(await api<any>("/api/v1/api-keys")).items}catch(e:any){error.value=e.message}} async function create(){try{const result=await api<any>("/api/v1/api-keys",{method:"POST",body:JSON.stringify({name:name.value,scopes:scopes.value,expires_in_days:90})});secret.value=result.api_key;name.value="";await load()}catch(e:any){error.value=e.message}} async function revoke(item:any){await api(`/api/v1/api-keys/${item.id}`,{method:"DELETE"});await load()} onMounted(load);
</script>
<template><section><h2>API Key</h2><el-alert v-if="error" :title="error" type="error"/><el-alert v-if="secret" type="warning" :closable="false" title="请立即复制；该 Key 只显示一次。"><template #default><code>{{secret}}</code></template></el-alert><el-form inline @submit.prevent="create"><el-form-item label="名称"><el-input v-model="name"/></el-form-item><el-form-item label="权限"><el-checkbox-group v-model="scopes"><el-checkbox label="retrieve"/><el-checkbox label="chat"/><el-checkbox label="documents:read"/><el-checkbox label="documents:write"/><el-checkbox label="documents:delete"/></el-checkbox-group></el-form-item><el-button type="primary" native-type="submit">创建</el-button></el-form><el-table :data="items"><el-table-column prop="name" label="名称"/><el-table-column prop="key_prefix" label="前缀"/><el-table-column label="权限"><template #default="s">{{s.row.scopes.join(', ')}}</template></el-table-column><el-table-column prop="expires_at" label="过期时间"/><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="revoke(s.row)">吊销</el-button></template></el-table-column></el-table></section></template>
